class Solution {
public:
    vector<int> largestDivisibleSubset(vector<int>& nums) {
        int n = nums.size();
        if (n == 0) return {};
        sort(nums.begin(), nums.end());

        vector<int> dp(n, 1), parent(n, -1);
        int maxSize = 1, maxIdx = 0;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (nums[i] % nums[j] == 0 && dp[j] + 1 > dp[i]) {
                    dp[i] = dp[j] + 1;
                    parent[i] = j;
                }
            }
            if (dp[i] > maxSize) {
                maxSize = dp[i];
                maxIdx = i;
            }
        }

        vector<int> ans;
        for (int cur = maxIdx; cur != -1; cur = parent[cur])
            ans.push_back(nums[cur]);
        reverse(ans.begin(), ans.end());
        return ans;
    }
};
